#!/usr/bin/env python3
"""markitai: write src/encodings/glyphnames/sorted_names.rs from the `glyphs!` list.

`Glyph::from_name` binary-searches the glyph names in byte order. This script
reads every `0xCODE = [name, ...];` line of the `glyphs!` invocation in
src/encodings/glyphnames.rs and writes all names, each with its code, sorted by
their bytes. A name may be listed once (it is also an associated constant).

    python3 scripts/sorted_glyph_names.py          # rewrite the table
    python3 scripts/sorted_glyph_names.py --check  # exit 1 if it is stale

Paths are relative to the crate root, wherever the script is run from.
"""
import re
import sys
from pathlib import Path

CRATE = Path(__file__).resolve().parent.parent
SOURCE = CRATE / 'src/encodings/glyphnames.rs'
TABLE = CRATE / 'src/encodings/glyphnames/sorted_names.rs'
ENTRY = re.compile(r'    (0x[0-9a-f]{4}) = \[([A-Za-z_][A-Za-z0-9_]*(?:, [A-Za-z_][A-Za-z0-9_]*)*)\];')


def listed_names():
    """The (name, code) pairs of the `glyphs!` invocation, in listing order."""
    lines = SOURCE.read_text().splitlines()
    start = lines.index('glyphs! {') + 1
    end = lines.index('}', start)
    names = []
    for line in lines[start:end]:
        entry = ENTRY.fullmatch(line)
        if not entry:
            sys.exit(f'unexpected line in glyphs!: {line!r}')
        code = int(entry.group(1), 16)
        names += [(name, code) for name in entry.group(2).split(', ')]
    return names


def render(names):
    seen = set()
    for name, _ in names:
        if name in seen:
            sys.exit(f'{name} is listed twice')
        seen.add(name)
    rows = ''.join(f'    ("{name}", 0x{code:04x}),\n' for name, code in sorted(names, key=lambda n: n[0].encode()))
    return (
        '// @generated by scripts/sorted_glyph_names.py from the `glyphs!` list in\n'
        '// src/encodings/glyphnames.rs (markitai); run it again after changing the list.\n'
        '\n'
        '/// Every glyph name with its code, in ascending byte order.\n'
        'pub(super) const SORTED_GLYPH_NAMES: &[(&str, u16)] = &[\n'
        f'{rows}'
        '];\n'
    )


def main():
    names = listed_names()
    text = render(names)
    if sys.argv[1:] == ['--check']:
        current = TABLE.read_text() if TABLE.exists() else ''
        if current != text:
            sys.exit(f'{TABLE.relative_to(CRATE)} is stale; run scripts/sorted_glyph_names.py')
        print(f'{TABLE.relative_to(CRATE)} is current ({len(names)} names)')
    elif not sys.argv[1:]:
        TABLE.write_text(text)
        print(f'wrote {TABLE.relative_to(CRATE)} ({len(names)} names)')
    else:
        sys.exit(__doc__)


if __name__ == '__main__':
    main()
